import math

def search(k, a):
	lt = 0
	rt = len(a) - 1
	ans = -1
	while lt <= rt:
		mid = lt + (rt - lt) // 2
		if a[mid] > k:
			rt = mid - 1
		if a[mid] <= k:
			lt = mid + 1
			ans = mid
	return ans

