					ans[element] = 0
				else:
					ans[element] = m
			for i in self.graph[element]:
				if i != self.parent[element]:
					ans[i] = max(ans[i] - ans[element], 0)
		return ans

	def shortestpath(self, source, dest):
		self.bfs(source)
		path = [dest]
