md = 10 ** 9 + 7

def mmul(a, b, adj):
	c0 = (a[0] * b[0] + a[1] * b[1] * adj) % md
	c1 = (a[0] * b[1] + a[1] * b[0]) % md
	return (c0, c1)

def mpow(b, adj, t):
	rv = (1, 0)
	while True:
		if t % 2 != 0:
			rv = mmul(rv, b, adj)
		t //= 2
		if t == 0:
			return rv
		b = mmul(b, b, adj)
