	def solve(self, string, k, index, maxi):
		if k <= 0 or index >= len(string) - 1:
			return
		max_ = string[index]
		for i in range(index + 1, len(string)):
			if int(max_) < int(string[i]):
				max_ = string[i]
		if string[index] != max_:
			k -= 1
		for i in range(index, len(string)):
