def grundy(k, ai):
	if k % 2:
		if ai <= 3:
			return G_ODD[ai]
		elif ai % 2:
			return 0
		else:
			p = 0
			j = ai
			while not j & 1:
				p += 1
				j >>= 1
			if j == 3:
				return 2 if p % 2 else 1
			else:
				return 1 if p % 2 else 2
			return 1 + p % 2
	elif ai <= 2:
		return G_EVEN[ai]
	else:
		return ~ai & 1

